def seed_initial_sequences(apps, schema_editor):
    TicketSequence = apps.get_model('weighbridge', 'TicketSequence')
    WeighTicket = apps.get_model('weighbridge', 'WeighTicket')
    EmergencyWeighTicket = apps.get_model('weighbridge', 'EmergencyWeighTicket')
    SystemSetting = apps.get_model('core', 'SystemSetting')

    db_alias = schema_editor.connection.alias

    # 1. Standard weighbridge tickets
    settings_obj = SystemSetting.objects.using(db_alias).first()
    prefix = settings_obj.serial_prefix.strip() if settings_obj and settings_obj.serial_prefix else "WB-"
    start_num = settings_obj.serial_start_number if settings_obj and settings_obj.serial_start_number else 1001

    highest_standard = 0
    for t in WeighTicket.objects.using(db_alias).all():
        digits = re.findall(r"\d+", t.serial_number or "")
        if digits:
            val = int("".join(digits))
            if val > highest_standard:
                highest_standard = val

    initial_standard_last = max(highest_standard, start_num - 1)
    TicketSequence.objects.using(db_alias).get_or_create(
        scope="standard",
        defaults={
            "prefix": prefix,
            "last_number": initial_standard_last,
            "description": "شمارنده توالی قبوض رسمی باسکول کارخانه",
        }
    )

    # 2. Emergency weighbridge tickets
    highest_emergency = 0
    for t in EmergencyWeighTicket.objects.using(db_alias).all():
        digits = re.findall(r"\d+", t.serial_number or "")
        if digits:
            val = int("".join(digits))
            if val > highest_emergency:
                highest_emergency = val

    initial_emergency_last = max(highest_emergency, 1000)
    TicketSequence.objects.using(db_alias).get_or_create(
        scope="emergency",
        defaults={
            "prefix": "EXT-",
            "last_number": initial_emergency_last,
            "description": "شمارنده توالی قبوض توزین متفرقه و اضطراری",
        }
    )


